echo '' | base64 -d > /tmp/clbci.zip
rm -rf /tmp/clbci; mkdir -p /tmp/clbci; unzip -oq /tmp/clbci.zip -d /tmp/clbci
export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/clbci; rm -rf $D; mkdir -p $D; cd $D
cp /tmp/clbci/*.v /tmp/clbci/*.tcl $D/
for t in p_ci0 p_ci1; do /opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source $t.tcl > $t.log 2>&1; if grep -q "DONE_$t" $t.log; then echo "OK $t"; else echo "FAIL $t"; grep -m3 "^ERROR" $t.log; fi; done
tar czf /tmp/clbci_out.tgz *.bit 2>/dev/null || echo NOTAR
echo CLBCIDONE
